import { test } from 'node:test';
import assert from 'node:assert/strict';
import { JOBS } from '../src/jobs/index.js';

// #9, #12: the 500 body is shown on the scheduler's admin screen; it must not carry the
// internal error text (see CONTRIBUTING.md). This covers every job in JOBS, so a job
// added later is checked without a test of its own.

// A db whose every method throws, whatever the job calls.
const brokenDb = (thrown) => new Proxy({}, { get: () => () => { throw thrown; } });

const THROWN = {
  'an Error': new Error('db down at 10.0.0.5'),
  'a non-Error value': 'db down at 10.0.0.5',
};

test('JOBS has jobs to check', () => {
  assert.ok(Object.keys(JOBS).length > 0);
});

for (const [name, job] of Object.entries(JOBS)) {
  for (const [what, thrown] of Object.entries(THROWN)) {
    test(`${name}: a 500 caused by ${what} has a fixed body without the internal error text`, () => {
      const res = job.run({ db: brokenDb(thrown), email: 'a@example.com' });
      assert.equal(res.status, 500);
      assert.deepEqual(res.body, { ok: false, error: 'internal error' });
      assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
    });
  }
}

